      "themeTag": "꾸준함",
      "icon": "🐢",
      "teaser": "느림보 거북이가 어떻게 쌩쌩 빠른 토끼를 달리기 시합에서 이겼을까요?",
      "characters": "빠른 토끼 🐰, 끈기 있는 거북이 🐢",
      "moral": "아무리 뛰어난 재주가 있어도 방심하면 실패하고, 비록 느려도 쉬지 않고 꾸준히 노력하면 끝내 승리합니다.",
      "dadTip": "은찬아! 공부나 운동을 할 때 처음부터 남보다 빠르지 않아도 괜찮단다. 매일 엉금엉금 조금씩이라도 앞으로 나아가는 친구가 결국 가장 멋진 1등이 된단다!",
