      "num": 2,
      "title": "개미와 베짱이",
      "enTitle": "The Ant and the Grasshopper",
      "theme": "정직과 성실",
      "themeTag": "근면성",
      "icon": "🐜",
      "teaser": "뜨거운 여름날 땀 흘린 개미와 바이올린을 켜며 놀던 베짱이의 겨울은 어땠을까요?",
