      "storyText": "햇볕이 쨍쨍 내리쬐는 무더운 여름날이었어요. 부지런한 개미들은 무거운 옥수수알과 빵 부스러기를 등에 지고 영차영차 줄을 지어 굴속으로 날랐어요. 땀이 비 오듯 쏟아졌지만 개미들은 쉬지 않았지요.\n\n그때 시원한 풀잎 그늘 아래에서 바이올린을 켜던 베짱이가 개미들을 비웃었어요. \"개미들아, 이 좋은 여름날에 왜 그렇게 힘들게 일만 하니? 나처럼 노래하고 춤추며 즐겁게 놀자!\"\n\n개미는 땀을 훔치며 대답했어요. \"베짱이야, 지금 음식을 모아두지 않으면 눈보라가 치는 추운 겨울에 먹을 것이 없단다. 너도 어서 겨울을 준비하렴.\"\n\n하지만 베짱이는 콧방귀를 뀌며 여름 내내 노래만 부르고 뒹굴뒹굴 놀았어요.\n\n어느덧 찬 바람이 쌩쌩 불고 하얀 눈이 온 세상을 뒤덮는 겨울이 찾아왔어요. 숲속의 풀잎과 열매는 모두 얼어붙었지요. 배가 고파 바들바들 떨던 베짱이는 마침내 따뜻한 불빛이 새어 나오는 개미네 집 문을 똑똑 두드렸어요.\n\n\"개미야, 제발 먹을 것 좀 나눠주라. 너무 춥고 배고파서 쓰러질 것 같아.\" 개미는 따뜻한 수프를 건네며 말했어요. \"베짱이야, 여름에 땀 흘려 일하지 않으면 겨울에 굶주린다는 걸 이제 알겠지? 내년 여름엔 꼭 우리와 함께 일하자꾸나.\"",
