      "storyText": "산비탈 풀밭에서 양 떼를 돌보던 양치기 소년이 있었어요. 매일매일 풀을 뜯는 양들만 바라보던 소년은 너무너무 심심했어요.\n\n'어디 재미있는 일 없을까? 그래, 마을 사람들을 골려주자!' 소년은 언덕 위로 뛰어가 양손을 입에 모으고 큰 소리로 외쳤어요. \"늑대다! 늑대가 나타났다! 도와주세요!\"\n\n마을 사람들은 깜짝 놀라 몽둥이와 괭이를 들고 숨을 헐떡이며 언덕으로 달려왔어요. 하지만 언덕에는 평화롭게 풀을 뜯는 양들뿐이었지요. 소년은 배를 잡고 뒹굴며 웃었어요. \"하하하! 속았지? 늑대는 없어요! 재미있다!\"\n\n며칠 뒤, 소년은 또 심심해지자 다시 외쳤어요. \"늑대다! 진짜 늑대가 나타났어요!\" 마을 사람들은 이번에도 헐레벌떡 달려왔지만, 또다시 소년의 장난에 속고 말았어요. 사람들은 화를 내며 고개를 가로저었어요.\n\n그런데 얼마 후, 해 질 무렵 정말로 눈빛이 번뜩이는 거대한 늑대가 숲속에서 으르렁거리며 나타났어요! 양 떼는 겁에 질려 우왕좌왕 도망쳤지요. 소년은 새파랗게 질려 목이 터져라 외쳤어요.\n\n\"늑대예요! 이번엔 진짜 늑대예요! 제발 도와주세요!\"\n\n하지만 마을 사람들은 \"흥, 또 우리를 속이려는 장난이겠지.\" 하며 아무도 돕지 않았어요. 결국 소년은 소중한 양들을 모두 잃고 눈물을 흘리며 후회했답니다.",
