      "storyText": "어느 날 하늘 위에서 바람과 해가 서로 자기가 더 힘이 세다고 말다툼을 벌이고 있었어요.\n\n바람이 으스대며 말했어요. \"해님아, 저 아래 길을 걸어가는 나그네가 보이지? 내가 입으로 후우- 불면 저 두꺼운 외투를 단숨에 날려버릴 수 있어!\"\n\n해님은 빙그레 웃으며 말했어요. \"그래? 그럼 누가 먼저 저 나그네의 외투를 벗기는지 내기를 해보자꾸나.\"\n\n바람이 먼저 나섰어요. \"크하하! 내 차례다!\" 바람은 숨을 크게 들이쉬더니 \"후우우우- 쌩쌩!\" 하고 세찬 비바람과 태풍 같은 강풍을 내뿜었어요. 나뭇가지가 부러지고 모자가 날아갔지요. 하지만 나그네는 외투가 벗겨지기는커녕, \"아이쿠, 날씨가 왜 이렇게 춥담!\" 하며 외투 깃을 더 꽁꽁 여미었어요.\n\n바람이 지쳐 씩씩거리고 있을 때, 이번에는 해님이 구름 뒤에서 살그머니 나왔어요. 해님은 따사로운 햇살을 온 세상에 부드럽게 비추기 시작했지요.\n\n햇살이 포근하게 내려앉자 얼어붙었던 땅이 녹고 꽃들이 피어났어요. 길을 걷던 나그네는 이마에 땀방울이 송골송골 맺히기 시작했어요. \"야, 갑자기 날씨가 봄날처럼 따뜻해졌네!\"\n\n나그네는 땀을 닦더니 자연스럽게 외투 단추를 풀고 외투를 훌훌 벗어 어깨에 멨답니다. 바람은 부끄러워 고개를 푹 숙였고, 해님은 부드러운 미소를 지었답니다.",
