      "storyText": "주인에게 늘 짐만 나르며 구박받던 당나귀가 어느 날 숲속 수풀에서 사냥꾼이 말리려고 널어둔 진짜 사자 가죽을 발견했어요.\n\n당나귀는 사자 가죽을 머리부터 발끝까지 뒤집어썼지요. 갈기가 풍성한 사자의 머리가 턱 얹어지자 거울에 비친 모습이 영락없는 밀림의 왕 사자였어요!\n\n\"히히, 이제 숲속 동물들이 나를 왕으로 모시겠지?\" 당나귀는 으스대며 숲으로 걸어 나갔어요. 토끼와 사슴, 멧돼지들이 가짜 사자를 보고 혼비백산하여 비명을 지르며 도망쳤어요.\n\n우쭐해진 당나귀는 바위 위에 올라서서 숲이 떠나가도록 사자의 무시무시한 포효를 지르고 싶었어요. 그러나 당나귀의 입에서 터져 나온 소리는 우렁찬 어흥!이 아니라, \"히히힝- 뻐꾹- 끼요오오옷!\" 하는 우스꽝스러운 당나귀 울음소리였어요!\n\n지나가던 영리한 여우가 귀를 쫑긋하더니 낄낄 웃으며 다가왔어요. \"사자 가죽을 썼을 때는 깜짝 속을 뻔했지만, 네 울음소리를 듣자마자 멍청한 당나귀인 줄 바로 알았단다!\"\n\n여우의 외침에 도망치던 동물들이 돌아와 당나귀를 골려주었고, 당나귀는 부끄러워 가죽을 벗어 던지고 도망쳤답니다.",
