      "storyText": "눈보라가 몰아치는 겨울날, 가난하지만 마음씨 고운 젊은 농부가 땔감을 구하러 산으로 가고 있었어요. 숲속 덤불에서 파닥파닥 처절한 날갯짓 소리가 들려 가보니, 눈부시게 흰 두루미 한 마리가 사냥꾼의 덫에 다리가 걸려 피를 흘리고 있었지요.\n\n\"쯧쯧, 얼마나 아팠을까! 조금만 참으렴.\" 농부는 얼어붙은 손으로 덫을 조심스럽게 풀고 상처를 치료해 주었어요. 두루미는 농부의 얼굴을 지그시 바라보더니 하늘 높이 훨훨 날아갔어요.\n\n그날 저녁, 농부의 오두막 문을 똑똑 두드리는 소리가 났어요. 문을 열어보니 눈처럼 하얀 옷을 입은 아름다운 처녀가 길을 잃었다며 하룻밤 묵어가게 해달라고 청했지요. 농부는 따뜻한 모닥불과 얼마 남지 않은 감자를 흔쾌히 나누어주었어요.\n\n처녀는 농부의 착한 마음에 감동하여 아내가 되었고, 방에서 밤낮으로 베를 짜기 시작했어요. \"여보, 제가 베를 짤 때는 절대로 방 안을 들여다보지 마세요.\" 처녀가 짠 비단은 세상 어디에서도 본 적 없는 신비로운 은빛 광채를 내뿜었고, 농부는 큰 부자가 되었어요.\n\n그러나 호기심을 참지 못한 농부가 몰래 문틈으로 방 안을 들여다보았어요. 방 안에는 처녀 대신 하얀 두루미가 자신의 가슴 깃털을 부리로 한 올씩 뽑아 피를 흘리며 눈물의 비단을 짜고 있었던 것이에요! 정체가 들통난 두루미는 눈물을 흘리며 은혜를 갚고 하늘나라로 돌아갔답니다.",
