      "moral": "혼자 떨어져 있으면 작은 힘에도 쉽게 부러지지만, 가족과 형제가 서로 사랑하고 단결하면 세상 어떤 어려움도 이겨낼 수 있습니다.",
      "dadTip": "은찬이와 동생 은우, 그리고 엄마와 아빠 우리 네 가족이 손을 꼭 잡고 사랑으로 뭉치면 세상에서 가장 무적의 행복한 가정이 된단다!",
